Lemma rrepfoot_where st m a : rmrep st m -> rrepfoot st a ->
  a < ATOP /\ (RCTX <= a < RCTX + 928 \/ RMLOCK <= a < RMLOCK + 4 \/ RLIBC <= a < RLIBC + 0x38
