Lemma RHEAP_init_proof : forall (m : mem) (auxv : word),
  (forall a : word, 0x5bba0 <= bv_unsigned a < 0x5bf48 -> m a = None) ->
  rw_cells usegs m 0x5bb30 [C1 (Z_to_bv 8 1); C1 (Z_to_bv 8 0); C1 (Z_to_bv 8 0); C1 (Z_to_bv 8 0); C4 (Z_to_bv 64 0)] ->
  rw_cells usegs m 0x5bb38 [C8 auxv; C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 224); C8 (Z_to_bv 64 8); C8 (Z_to_bv 64 0);
                            C8 (Z_to_bv 64 4096); CB 48 (repeat (Z_to_bv 8 0) 48)] ->
  rw_cells usegs m 0x2a528 [C8 (Z_to_bv 64 0x5bb10)] ->
  rw_cells usegs m 0x5bb10 [C8 CAN] ->
  mem_inv usegs m ->
  RHEAP (ps_init (reservedZ usegs) ATOP) [] m
